namespace generic.constraint;




/**
 * Special root node for a decision tree.  Root nodes don't have a real constraint, so 
 * a dummy constraint that is always satisfied is used.
 *
 * @param <T> the type of object used to test constraints.s
 */
public class RootDecisionNode<T> : DecisionNode<T> {

	public RootDecisionNode() : base(new DummyConstraint<T>(), null)
    {
	}

	/* @Override */
	protected List<string> getDecisionPath() {
		return new List<string>();
	}

	private static class DummyConstraint<T> : Constraint<T> {

		public DummyConstraint() : base("")
    {
		}

		/* @Override */
		public bool isSatisfied(T t) {
			return true;
		}

		/* @Override */
		public void loadConstraintData(ConstraintData data) {
			// nothing to load
		}

		/* @Override */
		public bool equals(object obj) {
			return this == obj;
		}

		/* @Override */
		public string getDescription() {
			return null;
		}

	}
}
